//! R10 exact Python-oracle capacity fixture parity; review only.
use serde_json::{json,Value};
use std::{fs,collections::BTreeMap};
fn vw(l:&[(f64,f64)],q:f64)->Option<f64>{let(mut x,mut t)=(q,0.);for&(p,a)in l{let z=x.min(a);t+=z*p;x-=z;if x<=q*1e-9{return Some(t/q)}}None}
fn smp(a:&[(f64,f64)],b:&[(f64,f64)],q:f64)->Option<f64>{let x=vw(a,q)?;let y=vw(b,q)?;if(y/x-1.)*10000.-24.>=42.{Some((x*q).max(y*q))}else{None}}
fn ck(t:&mut BTreeMap<u64,Option<f64>>,u:u64,a:&[(f64,f64)],b:&[(f64,f64)],step:f64)->Option<f64>{if let Some(v)=t.get(&u){return *v}let v=smp(a,b,u as f64*step);t.insert(u,v);v}
fn capacity(a:&[(f64,f64)],b:&[(f64,f64)],step:f64,minq:f64)->f64{let price=a[0].0.max(b[0].0);let first=(minq/step).round()as u64;let last=(((500./price)/step+1e-9).floor()as u64).max(first);let mut best=first;let mut t=BTreeMap::new();ck(&mut t,first,a,b,step);for usd in[10.,25.,50.,100.,200.,500.]{let u=last.min(((usd/price)/step+1e-9).floor()as u64);if u>=first&&ck(&mut t,u,a,b,step).is_some(){best=best.max(u)}}if ck(&mut t,last,a,b,step).is_some(){best=best.max(last)}let mut high=t.iter().filter(|(u,v)|**u>best&&v.is_none()).map(|(u,_)|*u).min().unwrap_or(last+1);for _ in 0..12{if high-best<=1{break}let m=(best+high)/2;if ck(&mut t,m,a,b,step).is_some(){best=m}else{high=m}}let v=ck(&mut t,best,a,b,step).unwrap_or(0.);(v.min(500.)*100.).round()/100.}
fn main(){let p:Vec<Value>=serde_json::from_str(&fs::read_to_string("/mnt/spotarb_db_test/r10_python_oracle.json").unwrap()).unwrap();let cases=[("ceiling",vec![(1.,1000.)],vec![(1.25,1000.)],0.1,1.),("depth120",vec![(1.,1000.)],vec![(1.0072,120.)],0.1,50.),("min57",vec![(1.,1000.)],vec![(1.0072,210.)],0.1,57.),("edgecross",vec![(1.,1000.)],vec![(1.008,15.),(1.003,600.)],0.1,1.)];let mut f=vec![];for(n,a,b,s,m)in cases{let r=capacity(&a,&b,s,m);let x=p.iter().find(|v|v["name"]==n).unwrap()["capacity"].as_f64().unwrap();if(r-x).abs()>0.011{f.push(json!({"name":n,"python":x,"rust":r}))}}println!("{}",json!({"r10_python_rust_capacity_parity":f.is_empty(),"cases":4,"mismatches":f.len(),"failures":f,"trading":false}));}